1	// Package govflow implements proposal lifecycle and treasury execution.
2	package govflow
3	
4	import "sort"
5	
6	// Proposal is one governance proposal with its voting window.
7	type Proposal struct {
8		ID           string
9		Title        string
10		State        string
11		ForVotes     int64
12		AgainstVotes int64
13		Quorum       int64
14		TimelockEnd  int64
15		Actions      []string
16	}
17	
18	// Vote records a weighted vote against an open proposal.
19	func Vote(proposal *Proposal, weight int64, support bool) error {
20		if proposal.State != "voting" {
21			return errInvalid("proposal is not open for voting")
22		}
23		if weight <= 0 {
24			return errInvalid("vote weight must be positive")
25		}
26		if support {
27			proposal.ForVotes += weight
28		} else {
29			proposal.AgainstVotes += weight
30		}
31		return nil
32	}
33	
34	// Tally returns the state a proposal moves to under quorum and majority rules.
35	func Tally(proposal *Proposal) string {
36		if proposal.State != "voting" {
37			return proposal.State
38		}
39		turnout := proposal.ForVotes + proposal.AgainstVotes
40		if turnout < proposal.Quorum {
41			return "rejected"
42		}
43		if proposal.ForVotes > proposal.AgainstVotes {
44			return "passed"
45		}
46		return "rejected"
47	}
48	
49	// Executable lists passed proposals whose timelock elapsed, stable by id.
50	func Executable(proposals []Proposal, now int64) []string {
51		var ready []string
52		for _, proposal := range proposals {
53			if proposal.State == "passed" && now >= proposal.TimelockEnd && len(proposal.Actions) > 0 {
54				ready = append(ready, proposal.ID)
55			}
56		}
57		sort.Strings(ready)
58		return ready
59	}
60	
61	type errInvalid string
62	
63	func (e errInvalid) Error() string { return string(e) }
