1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30		"unicode/utf8"
31	)
32	
33	// FormatVersion is the only registry file format understood by this build.
34	const FormatVersion = 1
35	
36	// MaxQuantity is the inclusive upper bound for a batch quantity.
37	const MaxQuantity = int64(1<<63 - 1)
38	
39	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
40	
41	// Batch is the four-piece record of one supply-chain batch.
42	type Batch struct {
43		Batch    string `json:"batch"`
44		Product  string `json:"product"`
45		Quantity int64  `json:"quantity"`
46		Unit     string `json:"unit"`
47	}
48	
49	// Registry is the on-disk registry file.
50	type Registry struct {
51		Version int     `json:"version"`
52		Batches []Batch `json:"batches"`
53	}
54	
55	// Input is a normalized registration request.
56	type Input struct {
57		Batch    string
58		Product  string
59		Quantity int64
60		Unit     string
61	}
62	
63	// Outcome reports what Register did.
64	type Outcome struct {
65		Batch   Batch
66		Created bool // true when a record was added, false for an identical repeat
67	}
68	
69	// ConflictError reports that a batch id is already held by a different record.
70	// Fields lists every differing member among "product", "quantity" and "unit".
71	type ConflictError struct {
72		Batch  string
73		Fields []string
74	}
75	
76	func (e *ConflictError) Error() string {
77		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
78			e.Batch, strings.Join(e.Fields, ", "))
79	}
80	
81	// DuplicateIDError reports two stored records sharing one batch id.
82	// First and Second are the 1-based positions of the two records in the
83	// batches array when known.
84	type DuplicateIDError struct {
85		Batch  string
86		First  int
87		Second int
88	}
89	
90	func (e *DuplicateIDError) Error() string {
91		if e.First > 0 && e.Second > 0 {
92			return fmt.Sprintf("registry contains multiple records for batch %q (records %d and %d)", e.Batch, e.First, e.Second)
93		}
94		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
95	}
96	
97	// FormatError reports a structural violation of the public registry file
98	// format: a missing, duplicated, misspelled, null or mistyped field, either
99	// in the root object (Position == 0) or in one batch record (Position is its
100	// 1-based index in "batches"). Batch carries the record's batch id only when
101	// it is uniquely determined; it stays empty when the "batch" member itself
102	// is missing, duplicated or not a string.
103	type FormatError struct {
104		Position int
105		Batch    string
106		Field    string
107		Reason   string
108	}
109	
110	func (e *FormatError) Error() string {
111		where := "root object"
112		if e.Position > 0 {
113			where = fmt.Sprintf("batches record %d", e.Position)
114			if e.Batch != "" {
115				where += fmt.Sprintf(" (batch %q)", e.Batch)
116			}
117		}
118		if e.Field != "" {
119			return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
120		}
121		return fmt.Sprintf("%s: %s", where, e.Reason)
122	}
123	
124	// EncodingError reports that a text field is not valid UTF-8: either the
125	// bytes of a CLI argument, or a JSON string value whose source bytes hold
126	// malformed UTF-8 or a lone surrogate escape. The offending value is never
127	// quoted back, since decoding it would substitute U+FFFD and make distinct
128	// inputs collide. Field is one of "batch", "product" and "unit". Inside a
129	// manifest, ParseManifest wraps this in a ManifestRecordError carrying the
130	// 1-based record position.
131	type EncodingError struct {
132		Field string
133	}
134	
135	func (e *EncodingError) Error() string {
136		return fmt.Sprintf("field %q contains bytes that are not valid UTF-8; the value is rejected instead of being replaced with U+FFFD", e.Field)
137	}
138	
139	// NormalizeField trims leading and trailing whitespace; the result must stay
140	// non-empty and be valid UTF-8. Interior characters, including interior
141	// whitespace, are kept, and casing is preserved so "B1" and "b1" are
142	// different values. A genuine replacement character (U+FFFD) is ordinary
143	// text; only malformed UTF-8 bytes are refused.
144	func NormalizeField(value string) (string, error) {
145		if !utf8.ValidString(value) {
146			return "", errors.New("value is not valid UTF-8 text")
147		}
148		trimmed := strings.TrimSpace(value)
149		if trimmed == "" {
150			return "", errors.New("value must not be empty after trimming whitespace")
151		}
152		return trimmed, nil
153	}
154	
155	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
156	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
157	// compared. Zero, signs, fractions, non-ASCII digits and values above the
158	// signed 64-bit maximum are rejected.
159	func ParseQuantity(text string) (int64, error) {
160		if !quantityPattern.MatchString(text) {
161			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
162		}
163		value, err := strconv.ParseInt(text, 10, 64)
164		if err != nil {
165			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
166		}
167		if value == 0 {
168			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
169		}
170		return value, nil
171	}
172	
173	var (
174		errStringNotJSON  = errors.New("value is not a JSON string")
175		errStringEncoding = errors.New("JSON string contains bytes that are not valid UTF-8")
176	)
177	
178	// unmarshalStringStrict decodes one JSON string literal into a Go string
179	// without encoding/json's silent U+FFFD substitution. The literal must be
180	// syntactically valid JSON (only the single token, no trailing data) and the
181	// decoded text must be valid Unicode: malformed UTF-8 source bytes and lone
182	// surrogate escapes are refused, while a genuine U+FFFD — written directly
183	// or as the escape "�" — is ordinary text. Syntax problems return
184	// errStringNotJSON; encoding problems return errStringEncoding.
185	func unmarshalStringStrict(raw json.RawMessage) (string, error) {
186		token := trimJSONSpace(raw)
187		if len(token) < 2 || token[0] != '"' || token[len(token)-1] != '"' {
188			return "", errStringNotJSON
189		}
190		var b strings.Builder
191		b.Grow(len(token))
192		i := 1
193		for i < len(token)-1 {
194			c := token[i]
195			switch {
196			case c == '"':
197				// An unescaped quote before the final byte ends the literal
198				// early, so anything following it is trailing data.
199				return "", errStringNotJSON
200			case c == '\\':
201				if i+1 >= len(token)-1 {
202					return "", errStringNotJSON
203				}
204				switch token[i+1] {
205				case '"', '\\', '/':
206					b.WriteByte(token[i+1])
207					i += 2
208				case 'b':
209					b.WriteByte('\b')
210					i += 2
211				case 'f':
212					b.WriteByte('\f')
213					i += 2
214				case 'n':
215					b.WriteByte('\n')
216					i += 2
217				case 'r':
218					b.WriteByte('\r')
219					i += 2
220				case 't':
221					b.WriteByte('\t')
222					i += 2
223				case 'u':
224					r, size, err := decodeUnicodeEscape(token[i:])
225					if err != nil {
226						return "", err
227					}
228					if _, err := b.WriteRune(r); err != nil {
229						return "", errStringEncoding
230					}
231					i += size
232				default:
233					return "", errStringNotJSON
234				}
235			case c < 0x20:
236				// Raw control characters must be escaped in JSON.
237				return "", errStringNotJSON
238			default:
239				r, size := utf8.DecodeRune(token[i : len(token)-1])
240				if r == utf8.RuneError && size == 1 {
241					return "", errStringEncoding
242				}
243				b.WriteRune(r)
244				i += size
245			}
246		}
247		if i != len(token)-1 {
248			return "", errStringNotJSON
249		}
250		return b.String(), nil
251	}
252	
253	// decodeUnicodeEscape reads a "\uXXXX" escape (or a UTF-16 surrogate pair
254	// "\uHHHH\uLLLL") at the start of p, returning the rune and the number of
255	// bytes consumed. A high surrogate not followed by a low surrogate, a low
256	// surrogate with no high one, or a non-hex code unit are encoding errors.
257	func decodeUnicodeEscape(p []byte) (rune, int, error) {
258		hi, ok := hex4(p)
259		if !ok {
260			return 0, 0, errStringNotJSON
261		}
262		switch {
263		case hi >= 0xD800 && hi <= 0xDBFF:
264			if len(p) < 12 || p[6] != '\\' || p[7] != 'u' {
265				return 0, 0, errStringEncoding
266			}
267			lo, ok := hex4(p[6:])
268			if !ok {
269				return 0, 0, errStringNotJSON
270			}
271			if lo < 0xDC00 || lo > 0xDFFF {
272				return 0, 0, errStringEncoding
273			}
274			return 0x10000 + (rune(hi)-0xD800)<<10 + (rune(lo) - 0xDC00), 12, nil
275		case hi >= 0xDC00 && hi <= 0xDFFF:
276			return 0, 0, errStringEncoding
277		default:
278			return rune(hi), 6, nil
279		}
280	}
281	
282	// hex4 reads the four hex digits following a leading "\u" (p[:2] == `\u`).
283	func hex4(p []byte) (int, bool) {
284		if len(p) < 6 || p[0] != '\\' || p[1] != 'u' {
285			return 0, false
286		}
287		v := 0
288		for _, c := range p[2:6] {
289			var d byte
290			switch {
291			case c >= '0' && c <= '9':
292				d = c - '0'
293			case c >= 'a' && c <= 'f':
294				d = c - 'a' + 10
295			case c >= 'A' && c <= 'F':
296				d = c - 'A' + 10
297			default:
298				return 0, false
299			}
300			v = v<<4 | int(d)
301		}
302		return v, true
303	}
304	
305	// Load reads the registry at path. A missing file yields an empty registry
306	// with existed == false. An existing file that is empty, not parseable as
307	// the public format — including missing, null, duplicated, misspelled or
308	// mistyped fields — of an unsupported version, or holding duplicate batch
309	// ids is an error: callers must never overwrite such a file as if it were a
310	// fresh registry.
311	func Load(path string) (reg *Registry, existed bool, err error) {
312		data, err := os.ReadFile(path)
313		if err != nil {
314			if errors.Is(err, fs.ErrNotExist) {
315				return &Registry{Version: FormatVersion}, false, nil
316			}
317			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
318		}
319		if len(bytes.TrimSpace(data)) == 0 {
320			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
321		}
322		reg, err = decode(data)
323		if err != nil {
324			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
325		}
326		if err := validate(reg); err != nil {
327			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
328		}
329		return reg, true, nil
330	}
331	
332	// decode parses data as the public registry format. The root must be a JSON
333	// object holding exactly "version" (the integer 1) and "batches" (an array,
334	// possibly empty); every record must be an object holding exactly "batch",
335	// "product", "quantity" and "unit". Field names are matched case-sensitively
336	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
337	// an escaped respelling such as "bat\u0063h" counts as the same field. A
338	// field appearing twice in one object is rejected even when both values are
339	// identical; missing fields, nulls, wrong types and unknown fields are
340	// rejected just the same. Nothing is patched up by taking the later value,
341	// merging or defaulting.
342	func decode(data []byte) (*Registry, error) {
343		dec := json.NewDecoder(bytes.NewReader(data))
344		var root json.RawMessage
345		if err := dec.Decode(&root); err != nil {
346			return nil, err
347		}
348		var extra json.RawMessage
349		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
350			if err == nil {
351				return nil, errors.New("unexpected data after registry object")
352			}
353			return nil, err
354		}
355	
356		fields, err := parseObjectFields(root)
357		if err != nil {
358			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
359		}
360		if dup, ok := duplicateField(fields); ok {
361			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
362		}
363		for _, f := range fields {
364			if f.key != "version" && f.key != "batches" {
365				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
366			}
367		}
368		versionRaw, ok := findField(fields, "version")
369		if !ok {
370			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
371		}
372		batchesRaw, ok := findField(fields, "batches")
373		if !ok {
374			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
375		}
376		version, err := parseRegistryVersion(versionRaw)
377		if err != nil {
378			return nil, err
379		}
380		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
381			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
382		}
383		var elems []json.RawMessage
384		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
385			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
386		}
387		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
388		for i, raw := range elems {
389			b, err := parseRegistryRecord(raw, i+1)
390			if err != nil {
391				return nil, err
392			}
393			reg.Batches = append(reg.Batches, b)
394		}
395		return reg, nil
396	}
397	
398	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
399	// Other integers report an unsupported version; anything else (strings,
400	// fractions, exponents, booleans, null, arrays, objects) is a type error.
401	func parseRegistryVersion(raw json.RawMessage) (int, error) {
402		token := string(bytes.TrimSpace(raw))
403		if isJSONInteger(token) {
404			if token == strconv.Itoa(FormatVersion) {
405				return FormatVersion, nil
406			}
407			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
408		}
409		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
410	}
411	
412	// parseRegistryRecord validates one batches element: a JSON object with
413	// exactly the four required lowercase fields, text fields as JSON strings
414	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
415	// record's 1-based position in the batches array.
416	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
417		var b Batch
418		fields, err := parseObjectFields(raw)
419		if err != nil {
420			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
421		}
422		// The batch id is attached to errors only when it is unambiguous:
423		// exactly one "batch" member carrying a JSON string whose decoded text
424		// is valid UTF-8. When the "batch" member itself is duplicated, or its
425		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
426		// picked arbitrarily.
427		batchID := ""
428		if countField(fields, "batch") == 1 {
429			if rawID, _ := findField(fields, "batch"); rawID != nil {
430				if id, idErr := unmarshalStringStrict(rawID); idErr == nil {
431					batchID = id
432				}
433			}
434		}
435		fail := func(field, reason string) (Batch, error) {
436			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
437		}
438	
439		if dup, ok := duplicateField(fields); ok {
440			return fail(dup, "field appears more than once; duplicate fields are not allowed")
441		}
442		for _, f := range fields {
443			if _, ok := batchRecordFields[f.key]; !ok {
444				return fail(f.key, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
445			}
446		}
447	
448		text := func(name string) (string, error) {
449			rawValue, ok := findField(fields, name)
450			if !ok {
451				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
452			}
453			if trimmed := bytes.TrimSpace(rawValue); len(trimmed) == 0 || trimmed[0] != '"' {
454				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
455			}
456			s, err := unmarshalStringStrict(rawValue)
457			if errors.Is(err, errStringEncoding) {
458				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
459					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
460			}
461			if err != nil {
462				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
463			}
464			return s, nil
465		}
466		if b.Batch, err = text("batch"); err != nil {
467			return Batch{}, err
468		}
469		if b.Product, err = text("product"); err != nil {
470			return Batch{}, err
471		}
472		if b.Unit, err = text("unit"); err != nil {
473			return Batch{}, err
474		}
475		quantityRaw, ok := findField(fields, "quantity")
476		if !ok {
477			return fail("quantity", "required field is missing")
478		}
479		b.Quantity, err = parseRegistryQuantity(bytes.TrimSpace(quantityRaw))
480		if err != nil {
481			return fail("quantity", err.Error())
482		}
483		return b, nil
484	}
485	
486	// parseRegistryQuantity accepts exactly a strict JSON integer token in the
487	// range 1..MaxQuantity. Strings, signs, fractions, exponents, null and
488	// out-of-range values are rejected.
489	func parseRegistryQuantity(token []byte) (int64, error) {
490		if !isJSONInteger(string(token)) || len(token) == 0 || token[0] == '-' {
491			return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
492		}
493		value, err := strconv.ParseInt(string(token), 10, 64)
494		if err != nil {
495			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
496		}
497		if value == 0 {
498			return 0, errors.New("must be greater than zero")
499		}
500		return value, nil
501	}
502	
503	// isJSONInteger reports whether token is a JSON number literal without
504	// fraction or exponent. The token comes from validated JSON, so leading
505	// zeros cannot hide extra digits.
506	func isJSONInteger(token string) bool {
507		if token == "" {
508			return false
509		}
510		if token[0] == '-' {
511			token = token[1:]
512		}
513		if token == "" {
514			return false
515		}
516		for i := 0; i < len(token); i++ {
517			if token[i] < '0' || token[i] > '9' {
518				return false
519			}
520		}
521		return true
522	}
523	
524	// objectField is one member of a JSON object in source order; the key is
525	// the decoded JSON string, so escaped spellings compare by meaning.
526	type objectField struct {
527		key   string
528		value json.RawMessage
529	}
530	
531	// parseObjectFields decodes a single JSON object value into its members in
532	// source order, keeping duplicates visible for the caller to reject. Keys
533	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
534	// substitutions for malformed key bytes.
535	func parseObjectFields(raw []byte) ([]objectField, error) {
536		trimmed := bytes.TrimSpace(raw)
537		if len(trimmed) == 0 || trimmed[0] != '{' {
538			return nil, errors.New("value is not a JSON object")
539		}
540		dec := json.NewDecoder(bytes.NewReader(trimmed))
541		if _, err := dec.Token(); err != nil { // opening brace
542			return nil, err
543		}
544		var fields []objectField
545		for dec.More() {
546			keyStart := dec.InputOffset()
547			tok, err := dec.Token()
548			keyEnd := dec.InputOffset()
549			if err != nil {
550				return nil, err
551			}
552			key, ok := tok.(string)
553			if !ok {
554				return nil, errors.New("object keys must be JSON strings")
555			}
556			if _, err := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd))); err != nil {
557				if errors.Is(err, errStringEncoding) {
558					return nil, errors.New("object key contains bytes that are not valid UTF-8")
559				}
560				return nil, err
561			}
562			var value json.RawMessage
563			if err := dec.Decode(&value); err != nil {
564				return nil, err
565			}
566			fields = append(fields, objectField{key: key, value: value})
567		}
568		if _, err := dec.Token(); err != nil { // closing brace
569			return nil, err
570		}
571		return fields, nil
572	}
573	
574	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
575	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
576	// other Unicode whitespace, which is illegal around a JSON token and must
577	// therefore be rejected rather than ignored.
578	func trimJSONSpace(b []byte) []byte {
579		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
580		for len(b) > 0 && isSpace(b[0]) {
581			b = b[1:]
582		}
583		for len(b) > 0 && isSpace(b[len(b)-1]) {
584			b = b[:len(b)-1]
585		}
586		return b
587	}
588	
589	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
590	// decoder reports the offset just after the preceding token (so the span
591	// may still contain a separating comma and whitespace), hence the left trim.
592	func keyTokenBytes(trimmed []byte, start, end int) []byte {
593		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
594	}
595	
596	// duplicateField returns the first field name appearing more than once.
597	func duplicateField(fields []objectField) (string, bool) {
598		seen := make(map[string]struct{}, len(fields))
599		for _, f := range fields {
600			if _, dup := seen[f.key]; dup {
601				return f.key, true
602			}
603			seen[f.key] = struct{}{}
604		}
605		return "", false
606	}
607	
608	// findField returns the raw value of the first member named name.
609	func findField(fields []objectField, name string) (json.RawMessage, bool) {
610		for _, f := range fields {
611			if f.key == name {
612				return f.value, true
613			}
614		}
615		return nil, false
616	}
617	
618	// countField counts the members named name.
619	func countField(fields []objectField, name string) int {
620		n := 0
621		for _, f := range fields {
622			if f.key == name {
623				n++
624			}
625		}
626		return n
627	}
628	
629	func validate(reg *Registry) error {
630		seen := make(map[string]int, len(reg.Batches))
631		for i, b := range reg.Batches {
632			pos := i + 1
633			if b.Batch == "" || b.Product == "" || b.Unit == "" {
634				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
635			}
636			if b.Quantity <= 0 {
637				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
638			}
639			if first, dup := seen[b.Batch]; dup {
640				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
641			}
642			seen[b.Batch] = pos
643		}
644		return nil
645	}
646	
647	// ManifestRecordError reports a manifest record that is structurally invalid
648	// or carries a quantity outside the accepted range. Position is the record's
649	// 1-based position in the manifest.
650	type ManifestRecordError struct {
651		Position int
652		Batch    string // normalized batch id when available, otherwise ""
653		Reason   string
654	}
655	
656	func (e *ManifestRecordError) Error() string {
657		if e.Batch != "" {
658			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
659		}
660		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
661	}
662	
663	// ManifestConflictError reports that a manifest record disagrees with the
664	// record already registered, or introduced earlier in the same manifest,
665	// under the same batch id. Position is the record's 1-based position in the
666	// manifest and Fields lists every differing member among "product",
667	// "quantity" and "unit" in that order.
668	type ManifestConflictError struct {
669		Position int
670		Batch    string
671		Fields   []string
672		Source   string // "registry" or "manifest"
673		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
674	}
675	
676	func (e *ManifestConflictError) Error() string {
677		if e.Source == "manifest" {
678			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
679				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
680		}
681		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
682			e.Position, e.Batch, strings.Join(e.Fields, ", "))
683	}
684	
685	// ParseManifest decodes data as a non-empty JSON array holding exactly the
686	// four required fields batch, product, quantity and unit per element. The
687	// three text fields must be JSON strings that are not blank after trimming;
688	// quantity must be a JSON integer (no strings, fractions or exponents) in
689	// the range 1..MaxQuantity. An empty file, empty array, non-array document
690	// or any malformed record is rejected. The manifest bytes are never written.
691	func ParseManifest(data []byte) ([]Input, error) {
692		trimmed := bytes.TrimSpace(data)
693		if len(trimmed) == 0 {
694			return nil, errors.New("manifest file is empty")
695		}
696		if trimmed[0] != '[' {
697			return nil, errors.New("manifest must be a non-empty JSON array of records")
698		}
699	
700		var elems []json.RawMessage
701		dec := json.NewDecoder(bytes.NewReader(data))
702		if err := dec.Decode(&elems); err != nil {
703			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
704		}
705		var extra json.RawMessage
706		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
707			if err == nil {
708				return nil, errors.New("manifest has unexpected data after the array")
709			}
710			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
711		}
712		if len(elems) == 0 {
713			return nil, errors.New("manifest must contain at least one record")
714		}
715	
716		inputs := make([]Input, 0, len(elems))
717		for i, raw := range elems {
718			pos := i + 1
719			in, err := parseManifestRecord(raw)
720			if err != nil {
721				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
722			}
723			inputs = append(inputs, in)
724		}
725		return inputs, nil
726	}
727	
728	// batchRecordFields are the only members a batch record may carry, in the
729	// registry file and in an import manifest alike.
730	var batchRecordFields = map[string]struct{}{
731		"batch": {}, "product": {}, "quantity": {}, "unit": {},
732	}
733	
734	// parseManifestRecord validates one manifest element: it must be a JSON
735	// object with exactly the four required keys, text fields as non-blank,
736	// valid UTF-8 strings and quantity as a strict JSON integer. The members
737	// are scanned with parseObjectFields (strict key decoding, duplicates kept
738	// visible) rather than a lenient map unmarshal, so malformed key or value
739	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
740	// fail — an unknown, duplicated or case-mismatched field included — the
741	// returned Input carries the normalized batch id whenever exactly one
742	// "batch" member holds valid, non-blank text, so the caller can name the
743	// batch in the error; otherwise it stays empty.
744	func parseManifestRecord(raw json.RawMessage) (Input, error) {
745		var in Input
746		members, err := parseObjectFields(raw)
747		if err != nil {
748			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
749		}
750		// Attach the batch id to whatever error this record raises, but only when
751		// it is unambiguous: exactly one "batch" member (compared after JSON key
752		// decoding, so an escaped respelling counts as the same field) carrying a
753		// JSON string whose decoded text is valid UTF-8 and non-blank once
754		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
755		// member leaves the id out — never a U+FFFD substitution, and never one
756		// of two duplicate values picked arbitrarily, even when both are equal.
757		// Where the "batch" member sits relative to the offending field does not
758		// matter.
759		if countField(members, "batch") == 1 {
760			if rawID, ok := findField(members, "batch"); ok {
761				if id, idErr := unmarshalStringStrict(rawID); idErr == nil {
762					if normalized, normErr := NormalizeField(id); normErr == nil {
763						in.Batch = normalized
764					}
765				}
766			}
767		}
768		fields := make(map[string]json.RawMessage, len(members))
769		for _, f := range members {
770			if _, ok := batchRecordFields[f.key]; !ok {
771				return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", f.key)
772			}
773			if _, dup := fields[f.key]; dup {
774				return in, fmt.Errorf("record lists field %q more than once", f.key)
775			}
776			fields[f.key] = f.value
777		}
778	
779		textField := func(name string) (string, error) {
780			value, ok := fields[name]
781			if !ok {
782				return "", fmt.Errorf("missing required field %q", name)
783			}
784			if trimmed := bytes.TrimSpace(value); len(trimmed) == 0 || trimmed[0] != '"' {
785				return "", fmt.Errorf("field %q must be a JSON string", name)
786			}
787			text, decodeErr := unmarshalStringStrict(value)
788			if errors.Is(decodeErr, errStringEncoding) {
789				return "", &EncodingError{Field: name}
790			}
791			if decodeErr != nil {
792				return "", fmt.Errorf("field %q must be a JSON string", name)
793			}
794			normalized, normErr := NormalizeField(text)
795			if normErr != nil {
796				return "", fmt.Errorf("field %q must not be blank: %w", name, normErr)
797			}
798			return normalized, nil
799		}
800	
801		in.Batch, err = textField("batch")
802		if err != nil {
803			return in, err
804		}
805		in.Product, err = textField("product")
806		if err != nil {
807			return in, err
808		}
809		in.Unit, err = textField("unit")
810		if err != nil {
811			return in, err
812		}
813		quantityRaw, ok := fields["quantity"]
814		if !ok {
815			return in, errors.New("missing required field \"quantity\"")
816		}
817		in.Quantity, err = parseManifestQuantity(bytes.TrimSpace(quantityRaw))
818		if err != nil {
819			return in, err
820		}
821		return in, nil
822	}
823	
824	// parseManifestQuantity accepts exactly a strict JSON integer token in the
825	// range 1..MaxQuantity. Strings, signs, fractions, exponents, leading zeros
826	// and out-of-range values are rejected instead of silently rounded.
827	func parseManifestQuantity(token []byte) (int64, error) {
828		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
829			return 0, fmt.Errorf("field %q must be a JSON integer between 1 and %d", "quantity", MaxQuantity)
830		}
831		for _, c := range token {
832			if c < '0' || c > '9' {
833				return 0, fmt.Errorf("field %q must be a JSON integer without sign, fraction or exponent", "quantity")
834			}
835		}
836		if len(token) > 1 && token[0] == '0' {
837			return 0, errors.New("field \"quantity\" must be a JSON integer without leading zeros")
838		}
839		value, err := strconv.ParseInt(string(token), 10, 64)
840		if err != nil {
841			return 0, fmt.Errorf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)
842		}
843		if value == 0 {
844			return 0, errors.New("field \"quantity\" must be greater than zero")
845		}
846		return value, nil
847	}
848	
849	// ImportResult is one entry of an Import outcome: the normalized record in
850	// manifest order plus whether it was newly created or already present.
851	type ImportResult struct {
852		Batch   Batch
853		Created bool
854	}
855	
856	// Import validates every record of inputs before appending anything: the
857	// whole manifest fails if any record conflicts with a stored record or with
858	// an earlier manifest record, and reg is left untouched on error. New batch
859	// ids are appended in first-occurrence order; an id already stored or
860	// introduced earlier in the same manifest is confirmed as a duplicate only
861	// when product, quantity and unit all match. Results come back in manifest
862	// order; Created is false for duplicates.
863	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
864		if reg.Version != FormatVersion {
865			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
866		}
867		if len(inputs) == 0 {
868			return nil, errors.New("manifest must contain at least one record")
869		}
870		// Reject malformed text before touching anything; every input must be
871		// valid UTF-8 so stored ids can never silently collapse onto U+FFFD.
872		for i, in := range inputs {
873			batchValid := utf8.ValidString(in.Batch)
874			for _, tv := range []struct{ field, value string }{
875				{"batch", in.Batch}, {"product", in.Product}, {"unit", in.Unit},
876			} {
877				if !utf8.ValidString(tv.value) {
878					err := &ManifestRecordError{Position: i + 1, Reason: (&EncodingError{Field: tv.field}).Error()}
879					if tv.field != "batch" && batchValid && in.Batch != "" {
880						err.Batch = in.Batch
881					}
882					return nil, err
883				}
884			}
885		}
886	
887		// Work on a copy: a rejected manifest must never partially land in reg.
888		working := append([]Batch(nil), reg.Batches...)
889		indexByID := make(map[string]int, len(working))
890		for i, b := range working {
891			indexByID[b.Batch] = i
892		}
893		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
894	
895		out := make([]ImportResult, len(inputs))
896		for i, in := range inputs {
897			pos := i + 1
898			if idx, known := indexByID[in.Batch]; known {
899				existing := working[idx]
900				diffs := diffFields(existing, in)
901				if len(diffs) > 0 {
902					if prev, inManifest := firstPos[in.Batch]; inManifest {
903						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
904					}
905					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
906				}
907				out[i] = ImportResult{Batch: existing, Created: false}
908				continue
909			}
910			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
911			working = append(working, b)
912			indexByID[in.Batch] = len(working) - 1
913			firstPos[in.Batch] = pos
914			out[i] = ImportResult{Batch: b, Created: true}
915		}
916	
917		reg.Batches = working
918		return out, nil
919	}
920	
921	// diffFields lists the members of product, quantity and unit in which in
922	// differs from existing, in that fixed order.
923	func diffFields(existing Batch, in Input) []string {
924		var diffs []string
925		if existing.Product != in.Product {
926			diffs = append(diffs, "product")
927		}
928		if existing.Quantity != in.Quantity {
929			diffs = append(diffs, "quantity")
930		}
931		if existing.Unit != in.Unit {
932			diffs = append(diffs, "unit")
933		}
934		return diffs
935	}
936	
937	// Register adds in to reg, or confirms the identical record already stored
938	// under the same batch id. A batch id held by a record differing in product,
939	// quantity or unit produces a *ConflictError and leaves reg untouched. The
940	// zero Outcome is returned together with the error.
941	func Register(reg *Registry, in Input) (Outcome, error) {
942		if reg.Version != FormatVersion {
943			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
944		}
945		if in.Batch == "" || in.Product == "" || in.Unit == "" {
946			return Outcome{}, errors.New("batch, product and unit must be non-empty")
947		}
948		for _, tv := range []struct{ field, value string }{
949			{"batch", in.Batch}, {"product", in.Product}, {"unit", in.Unit},
950		} {
951			if !utf8.ValidString(tv.value) {
952				return Outcome{}, &EncodingError{Field: tv.field}
953			}
954		}
955		if in.Quantity <= 0 || in.Quantity > MaxQuantity {
956			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
957		}
958		for _, b := range reg.Batches {
959			if b.Batch != in.Batch {
960				continue
961			}
962			var diffs []string
963			if b.Product != in.Product {
964				diffs = append(diffs, "product")
965			}
966			if b.Quantity != in.Quantity {
967				diffs = append(diffs, "quantity")
968			}
969			if b.Unit != in.Unit {
970				diffs = append(diffs, "unit")
971			}
972			if len(diffs) > 0 {
973				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
974			}
975			return Outcome{Batch: b, Created: false}, nil
976		}
977		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
978		reg.Batches = append(reg.Batches, b)
979		return Outcome{Batch: b, Created: true}, nil
980	}
981	
982	// Save atomically writes reg to path, replacing the file only after the new
983	// content is fully on disk so an existing registry stays usable on failure.
984	// Records are serialized in their current order; the file is created with
985	// 0644 permissions or, when replacing an existing file, with its permissions.
986	func Save(path string, reg *Registry) error {
987		if reg.Version != FormatVersion {
988			return fmt.Errorf("cannot write registry format version %d", reg.Version)
989		}
990		// Never persist U+FFFD substitutions: every text field must round-trip
991		// as valid UTF-8. Load already guarantees this; the guard also covers
992		// registries assembled by hand inside other code.
993		for i, b := range reg.Batches {
994			for _, tv := range []struct{ field, value string }{
995				{"batch", b.Batch}, {"product", b.Product}, {"unit", b.Unit},
996			} {
997				if !utf8.ValidString(tv.value) {
998					return fmt.Errorf("cannot save registry %q: batches record %d field %q is not valid UTF-8", path, i+1, tv.field)
999				}
1000			}
1001		}
1002		mode := os.FileMode(0o644)
1003		if info, err := os.Stat(path); err == nil {
1004			mode = info.Mode().Perm()
1005		} else if !errors.Is(err, fs.ErrNotExist) {
1006			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1007		}
1008	
1009		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
1010			return fmt.Errorf("cannot save registry %q: %w", path, err)
1011		}
1012	
1013		var buf bytes.Buffer
1014		enc := json.NewEncoder(&buf)
1015		enc.SetEscapeHTML(false)
1016		enc.SetIndent("", "  ")
1017		if err := enc.Encode(reg); err != nil {
1018			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1019		}
1020	
1021		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
1022		if err != nil {
1023			return fmt.Errorf("cannot save registry %q: %w", path, err)
1024		}
1025		tmpName := tmp.Name()
1026		abort := func(cause error) error {
1027			tmp.Close()
1028			os.Remove(tmpName)
1029			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1030		}
1031		if _, err := tmp.Write(buf.Bytes()); err != nil {
1032			return abort(err)
1033		}
1034		if err := tmp.Chmod(mode); err != nil {
1035			return abort(err)
1036		}
1037		if err := tmp.Sync(); err != nil {
1038			return abort(err)
1039		}
1040		if err := tmp.Close(); err != nil {
1041			os.Remove(tmpName)
1042			return fmt.Errorf("cannot save registry %q: %w", path, err)
1043		}
1044		if err := os.Rename(tmpName, path); err != nil {
1045			os.Remove(tmpName)
1046			return fmt.Errorf("cannot save registry %q: %w", path, err)
1047		}
1048		return nil
1049	}
1050

