292			// Duplicate fields are rejected even when both values are identical,
293			// and even when the repeat hides behind a JSON escape.
294			"root duplicate version":   `{"version":1,"version":1,"batches":[]}`,
295			"root duplicate batches":   `{"version":1,"batches":[{"batch":"B","product":"P","quantity":1,"unit":"kg"}],"batches":[]}`,
296			"root duplicate escaped":   `{"version":1,"\u0076ersion":1,"batches":[]}`,
297			"record duplicate field":   `{"version":1,"batches":[{"batch":"B","product":"P","quantity":1,"unit":"kg","unit":"kg"}]}`,
298			"record duplicate escaped": `{"version":1,"batches":[{"batch":"B","produc\u0074":"P","product":"P","quantity":1,"unit":"kg"}]}`,
299			// Missing or null members of the root object.
300			"missing version": `{"batches":[]}`,
301			"missing batches": `{"version":1}`,
302			"null version":    `{"version":null,"batches":[]}`,
303			"null batches":    `{"version":1,"batches":null}`,
304			// Wrong types.
305			"string version": `{"version":"1","batches":[]}`,
306			"float version":  `{"version":1.0,"batches":[]}`,
307			"batches object": `{"version":1,"batches":{}}`,
308			"batches string": `{"version":1,"batches":"[]"}`,
309			// Field names are matched case-sensitively.
310			"capitalized root":   `{"Version":1,"batches":[]}`,
311			"capitalized record": `{"version":1,"batches":[{"Batch":"B","product":"P","quantity":1,"unit":"kg"}]}`,
312			// Record-level structural problems.
313			"record not object":      `{"version":1,"batches":[null]}`,
314			"record missing field":   `{"version":1,"batches":[{"batch":"B","product":"P","quantity":1}]}`,
315			"record null field":      `{"version":1,"batches":[{"batch":"B","product":null,"quantity":1,"unit":"kg"}]}`,
