320			"record unknown field":   `{"version":1,"batches":[{"batch":"B","product":"P","quantity":1,"unit":"kg","note":"x"}]}`,
321		}
322		for name, content := range cases {
323			t.Run(name, func(t *testing.T) {
324				path := filepath.Join(dir, name+".json")
