552			{"escaped unknown field name", `{"batch":"B-002","product":"P","quantity":1,"unit":"kg","supplie\u0072":"S"}`, 1, "B-002", "supplier"},
553			{"escaped batch spelling", `{"bat\u0063h":"B-002","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "B-002", "extra"},
554			{"unicode batch", `{"batch":"批次-🚚","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "批次-🚚", "extra"},
555			{"genuine replacement char batch", `{"batch":"�","product":"P","quantity":1,"unit":"kg","extra":1}`, 1, "�", "extra"},
