616	func TestImportCreatesAndConfirmsRepeats(t *testing.T) {
617		reg := &Registry{Version: FormatVersion, Batches: []Batch{
618			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},
619		}}
620		inputs := []Input{
621			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"},
622			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // same-manifest duplicate
623			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},    // stored duplicate
624			{Batch: "NEW2", Product: "P-3", Quantity: 1, Unit: "m"},
625		}
626		out, err := Import(reg, inputs)
627		if err != nil {
628			t.Fatal(err)
629		}
630		wantCreated := []bool{true, false, false, true}
631		for i, want := range wantCreated {
632			if out[i].Created != want {
633				t.Errorf("record %d created=%v, want %v", i+1, out[i].Created, want)
634			}
635			if out[i].Batch.Batch != inputs[i].Batch {
636				t.Errorf("record %d batch=%q", i+1, out[i].Batch.Batch)
637			}
638		}
639		// Stored record first, new batches appended in first-occurrence order.
640		wantBatches := []string{"OLD", "NEW1", "NEW2"}
641		if len(reg.Batches) != len(wantBatches) {
642			t.Fatalf("got %d stored batches: %+v", len(reg.Batches), reg.Batches)
643		}
644		for i, want := range wantBatches {
645			if reg.Batches[i].Batch != want {
646				t.Errorf("stored batch %d = %q, want %q", i, reg.Batches[i].Batch, want)
647			}
648		}
649	}
