		"record quantity null":   `{"version":1,"batches":[{"batch":"B","product":"P","quantity":null,"unit":"kg"}]}`,
		"record quantity minus":  `{"version":1,"batches":[{"batch":"B","product":"P","quantity":-3,"unit":"kg"}]}`,
