	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(dir, name+".json")
			writeRegistry(t, path, content)
			if _, _, err := Load(path); err == nil {
				t.Fatalf("expected rejection of %s", content)
			}
		})
	}
}

