281				if !errors.As(err, &ee) || ee.Field != tc.field {
282					t.Fatalf("got %v, want EncodingError on field %q", err, tc.field)
283				}
284				if len(reg.Batches) != 0 {
285					t.Fatalf("rejected register appended a record: %+v", reg.Batches)
286				}
287			})
288		}
289	}
290	
291	func TestSaveEncodingGuardCreatesNothing(t *testing.T) {
292		path := filepath.Join(t.TempDir(), "nested", "registry.json")
293		reg := &Registry{Version: FormatVersion, Batches: []Batch{
294			{Batch: "OK", Product: "P", Quantity: 1, Unit: "kg"},
295			// A genuine U+FFFD is valid text and saves fine.
296			{Batch: "B" + string(rune(0xfffd)), Product: "P", Quantity: 2, Unit: "kg"},
297			{Batch: string([]byte{'X', 0xff}), Product: "P", Quantity: 3, Unit: "kg"},
298		}}
299		if err := Save(path, reg); err == nil {
300			t.Fatal("Save must refuse to persist malformed UTF-8")
301		}
302		if _, err := os.Stat(path); !os.IsNotExist(err) {
303			t.Fatalf("failed Save must leave no registry, stat err=%v", err)
304		}
305	}
