29			Unit     string `json:"unit"`
30			Status   string `json:"status"`
31		} `json:"results"`
32	}
33	
34	func TestBatchImportCLICreatesRegistry(t *testing.T) {
35		dir := t.TempDir()
36		registry := filepath.Join(dir, "nested", "reg.json")
37		manifest := filepath.Join(dir, "in.json")
38		writeFile(t, manifest, `[
39	  {"batch": " B1 ", "product": "P-7", "quantity": 120, "unit": "kg"},
40	  {"batch": "B1", "product": "P-7", "quantity": 120, "unit": "kg"},
41	  {"batch": "B2", "product": "P-8", "quantity": 1, "unit": "box"}
42	]`)
43	
44		var stdout bytes.Buffer
45		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
46			t.Fatalf("import failed: %v", err)
47		}
48		var out importOutput
49		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
50			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
51		}
52		wantStatus := []string{"created", "duplicate", "created"}
53		if len(out.Results) != len(wantStatus) {
54			t.Fatalf("got %d results", len(out.Results))
55		}
56		for i, want := range wantStatus {
57			if out.Results[i].Status != want {
58				t.Errorf("result %d status = %q, want %q", i+1, out.Results[i].Status, want)
59			}
60			if out.Results[i].Batch != "B1" && i < 2 {
61				t.Errorf("result %d batch = %q, want trimmed B1", i+1, out.Results[i].Batch)
62			}
63		}
64	
65		data, err := os.ReadFile(registry)
66		if err != nil {
67			t.Fatal(err)
68		}
69		var stored struct {
70			Version int `json:"version"`
71			Batches []struct {
72				Batch    string `json:"batch"`
73				Quantity int64  `json:"quantity"`
74			} `json:"batches"`
75		}
76		if err := json.Unmarshal(data, &stored); err != nil {
77			t.Fatal(err)
78		}
79		if stored.Version != 1 || len(stored.Batches) != 2 {
80			t.Fatalf("unexpected registry content: %s", data)
81		}
82		if stored.Batches[0].Batch != "B1" || stored.Batches[1].Batch != "B2" {
83			t.Fatalf("new batches not appended in first-occurrence order: %s", data)
