86	
87	func TestBatchImportCLIAllDuplicatesLeavesFileUntouched(t *testing.T) {
88		dir := t.TempDir()
89		registry := filepath.Join(dir, "reg.json")
90		manifest := filepath.Join(dir, "in.json")
91		writeFile(t, registry, `{"version":1,"batches":[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]}`)
92		writeFile(t, manifest, `[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]`)
93	
94		// Pin a distinctive past mtime so any rewrite is observable even on
95		// filesystems with coarse timestamp granularity.
96		pinned := time.Date(2001, time.February, 3, 4, 5, 6, 0, time.UTC)
97		if err := os.Chtimes(registry, pinned, pinned); err != nil {
98			t.Fatal(err)
99		}
100		before, err := os.ReadFile(registry)
101		if err != nil {
102			t.Fatal(err)
103		}
104	
105		var stdout bytes.Buffer
106		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
107			t.Fatalf("import failed: %v", err)
108		}
109		if !strings.Contains(stdout.String(), `"status":"duplicate"`) {
110			t.Fatalf("expected duplicate result, got %q", stdout.String())
111		}
112	
113		after, err := os.ReadFile(registry)
114		if err != nil {
115			t.Fatal(err)
116		}
117		if !bytes.Equal(before, after) {
118			t.Fatal("all-duplicate import rewrote the registry bytes")
119		}
120		info, err := os.Stat(registry)
121		if err != nil {
122			t.Fatal(err)
123		}
124		if !info.ModTime().Equal(pinned) {
125			t.Fatalf("all-duplicate import changed mtime: got %v, want %v", info.ModTime(), pinned)
126		}
127	}
128	
129	func TestBatchImportCLIRejectsAndPreserves(t *testing.T) {
130		cases := map[string]string{
131			"empty file":      "",
132			"empty array":     "[]",
133			"object":          "{}",
134			"quantity string": `[{"batch":"B","product":"P","quantity":"1","unit":"kg"}]`,
135			"quantity float":  `[{"batch":"B","product":"P","quantity":1.0,"unit":"kg"}]`,
136			"missing field":   `[{"batch":"B","product":"P","quantity":1}]`,
137			"unknown field":   `[{"batch":"B","product":"P","quantity":1,"unit":"kg","x":1}]`,
138			"blank batch":     `[{"batch":"  ","product":"P","quantity":1,"unit":"kg"}]`,
139		}
140		for name, content := range cases {
141			t.Run(name, func(t *testing.T) {
142				dir := t.TempDir()
143				registry := filepath.Join(dir, "reg.json")
144				manifest := filepath.Join(dir, "in.json")
145				writeFile(t, manifest, content)
146	
147				var stdout bytes.Buffer
148				err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout)
149				if err == nil {
150					t.Fatal("expected rejection")
151				}
152				if stdout.Len() != 0 {
153					t.Fatalf("stdout must stay empty on failure, got %q", stdout.String())
154				}
155				if _, statErr := os.Stat(registry); !os.IsNotExist(statErr) {
156					t.Fatal("a rejected import must not create the registry file")
157				}
158			})
159		}
160	}
161	
162	// A record rejected for an unknown, duplicated or case-mismatched field must
163	// name the manifest path, the 1-based record position, the normalized batch
164	// id and the offending field — and leave both files untouched.
165	func TestBatchImportCLIFieldErrorNamesBatch(t *testing.T) {
166		cases := map[string]struct {
167			record    string
168			wantBatch string
169			wantField string
170		}{
171			"unknown field":         {`{"batch":" B-002 ","product":"P","quantity":1,"unit":"kg","supplier":"S"}`, "B-002", "supplier"},
172			"duplicate product":     {`{"batch":"B-002","product":"P","product":"P","quantity":1,"unit":"kg"}`, "B-002", "product"},
173			"case-mismatched field": {`{"batch":"B-002","Product":"P","product":"P","quantity":1,"unit":"kg"}`, "B-002", "Product"},
174			"duplicate batch":       {`{"batch":"B-002","batch":"B-002","product":"P","quantity":1,"unit":"kg"}`, "", "batch"},
175		}
176		for name, tc := range cases {
177			t.Run(name, func(t *testing.T) {
178				dir := t.TempDir()
179				registry := filepath.Join(dir, "reg.json")
180				manifest := filepath.Join(dir, "in.json")
181				original := `{"version":1,"batches":[{"batch":"B-001","product":"P","quantity":1,"unit":"kg"}]}`
182				writeFile(t, registry, original)
183				writeFile(t, manifest, `[
184	  {"batch":"B-001","product":"P","quantity":1,"unit":"kg"},
185	  `+tc.record+`
186	]`)
187	
188				var stdout bytes.Buffer
189				err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout)
190				if err == nil {
191					t.Fatal("expected rejection")
192				}
193				msg := err.Error()
194				for _, want := range []string{manifest, "record 2", strconv.Quote(tc.wantField)} {
195					if !strings.Contains(msg, want) {
196						t.Fatalf("error must contain %q: %v", want, msg)
197					}
198				}
199				if tc.wantBatch != "" {
200					if !strings.Contains(msg, "batch "+strconv.Quote(tc.wantBatch)) {
201						t.Fatalf("error must name batch %q: %v", tc.wantBatch, msg)
202					}
203				} else if strings.Contains(msg, "batch \"") {
204					t.Fatalf("error must not quote a batch id: %v", msg)
205				}
206				if stdout.Len() != 0 {
207					t.Fatalf("stdout must stay empty on failure, got %q", stdout.String())
208				}
209				after, rerr := os.ReadFile(registry)
210				if rerr != nil {
211					t.Fatal(rerr)
212				}
213				if string(after) != original {
214					t.Fatalf("registry changed: %s", after)
215				}
216			})
217		}
218	}
219	
220	func TestBatchImportCLIConflictPreservesRegistry(t *testing.T) {
221		dir := t.TempDir()
222		registry := filepath.Join(dir, "reg.json")
223		manifest := filepath.Join(dir, "in.json")
224		original := `{"version":1,"batches":[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]}`
